9	// Record 是一次成功保存留下的、可供读取的记录。
10	type Record struct {
11		// ID 是记录标识。
12		ID RecordID
13		// Parent 是父记录标识；槽首条记录为空。
14		Parent RecordID
15		// SlotFirst 表示这是其所在槽的首条记录。
16		SlotFirst bool
17		// State 是记录保存时的完整世界数据（深拷贝，修改不影响存档）。
18		State State
19	}
20	
21	func acquireSharedLock(dir string) (*fileLock, error) {
22		path := dir + "/lock"
23		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
24		if err != nil {
25			return nil, err
26		}
27		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
28			f.Close()
29			return nil, err
30		}
31		return &fileLock{f: f}, nil
32	}
33	
34	// loadAndVerifyLocked 读取记录文件，校验其内容校验和（校验和已包含
35	// 父记录关系）、父记录是否存在，以及世界数据是否自洽。
36	func (a *Archive) loadAndVerifyLocked(id RecordID) (*envelope, error) {
37		env, err := loadRecord(recordPath(a.dir, id))
38		if err != nil {
39			if errors.Is(err, os.ErrNotExist) {
40				return nil, &NotFoundError{Record: id}
41			}
42			return nil, &CorruptError{Record: id, Reason: err.Error()}
43		}
44		if env.ID != id {
45			return nil, &CorruptError{Record: id, Reason: "记录标识与文件名不一致"}
46		}
47		if got := computeChecksum(env); got != env.Checksum {
48			return nil, &CorruptError{Record: id, Reason: "内容校验和不匹配（可能已损坏或被改动）"}
49		}
50		// 父记录关系必须落到一个真实存在的记录上。
51		if env.Parent != "" {
52			if _, err := os.Stat(recordPath(a.dir, env.Parent)); err != nil {
53				if errors.Is(err, os.ErrNotExist) {
54					return nil, &CorruptError{Record: id, Reason: "父记录缺失: " + string(env.Parent)}
55				}
56				return nil, err
57			}
58		}
59		if err := validateInitialData(InitialData{
60			Seed:       env.State.Seed,
61			Rules:      env.State.Rules,
62			Characters: env.State.Characters,
63		}); err != nil {
64			return nil, &CorruptError{Record: id, Reason: "记录中的世界数据不合法: " + err.Error()}
65		}
66		return env, nil
67	}
68	
69	func versionAccepted(version string, accepted []string) bool {
70		for _, v := range accepted {
71			if v == version {
72				return true
73			}
74		}
75		return false
76	}
77	
78	func envToRecord(env *envelope) Record {
79		return Record{
80			ID:        env.ID,
81			Parent:    env.Parent,
82			SlotFirst: env.SlotFirst,
83			State:     cloneState(env.State),
84		}
85	}
86	
87	// Latest 读取槽当前最新记录。
88	//
89	// acceptedVersions 是调用方明确给出的可接受规则版本集合：记录完好但
90	// 版本不在集合内时返回 *VersionRejectedError；记录损坏（校验和不符、
91	// 父记录缺失、无法解析）时返回 *CorruptError。读取不会改写存档。
92	func (a *Archive) Latest(slot string, acceptedVersions []string) (Record, error) {
93		if !validSlotName(slot) {
94			return Record{}, &NotFoundError{Slot: slot}
95		}
96		lock, err := acquireSharedLock(a.dir)
97		if err != nil {
98			return Record{}, err
99		}
100		defer lock.release()
101	
102		id, err := a.readLatestLocked(slot)
103		if err != nil {
104			return Record{}, err
105		}
106		env, err := a.loadAndVerifyLocked(id)
107		if err != nil {
108			if ce, ok := err.(*CorruptError); ok {
109				ce.Slot = slot
110			}
111			return Record{}, err
112		}
113		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
114			return Record{}, &VersionRejectedError{
115				Slot:     slot,
116				Record:   id,
117				Version:  env.State.Rules.Version,
118				Accepted: append([]string(nil), acceptedVersions...),
119			}
120		}
121		return envToRecord(env), nil
122	}
123	
124	// Record 按标识读取槽的一份历史记录（覆盖后的旧记录仍可读取）。
125	//
126	// 与 Latest 一样检查内容校验和（含父记录关系）与规则版本，且记录必须
127	// 属于该槽的历史链。读取不会改写存档，也不会改变规则版本。
128	func (a *Archive) Record(slot string, id RecordID, acceptedVersions []string) (Record, error) {
129		if !validSlotName(slot) {
130			return Record{}, &NotFoundError{Slot: slot}
131		}
132		lock, err := acquireSharedLock(a.dir)
133		if err != nil {
134			return Record{}, err
135		}
136		defer lock.release()
137	
138		if err := a.assertInSlotHistoryLocked(slot, id); err != nil {
139			return Record{}, err
140		}
141		env, err := a.loadAndVerifyLocked(id)
142		if err != nil {
143			if ce, ok := err.(*CorruptError); ok {
144				ce.Slot = slot
145			}
146			return Record{}, err
147		}
148		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
149			return Record{}, &VersionRejectedError{
150				Slot:     slot,
151				Record:   id,
152				Version:  env.State.Rules.Version,
153				Accepted: append([]string(nil), acceptedVersions...),
154			}
155		}
156		return envToRecord(env), nil
157	}
158	
159	// History 返回槽的历史记录元信息，按该槽保存生效的次序排列（最新在
160	// 前），到槽首条记录为止；分支槽只含它自己保存成功的记录，不会跨入
161	// 分支来源槽。次序来自槽指针内嵌的历史索引，与文件修改时间无关。该
162	// 方法只做只读遍历，不改写任何数据；无法解析的记录会被略过。
163	func (a *Archive) History(slot string) ([]RecordInfo, error) {
164		if !validSlotName(slot) {
165			return nil, &NotFoundError{Slot: slot}
166		}
167		lock, err := acquireSharedLock(a.dir)
168		if err != nil {
169			return nil, err
170		}
171		defer lock.release()
172	
173		history, err := a.slotHistoryLocked(slot)
174		if err != nil {
175			return nil, err
176		}
177		infos := make([]RecordInfo, 0, len(history))
178		for _, id := range history {
179			env, err := loadRecord(recordPath(a.dir, id))
180			if err != nil {
181				continue
182			}
183			infos = append(infos, RecordInfo{
184				ID:        env.ID,
185				Parent:    env.Parent,
186				SlotFirst: env.SlotFirst,
187				Version:   env.State.Rules.Version,
188			})
189		}
190		return infos, nil
191	}
192	
193	// RecoverLatest 返回该槽“按保存生效次序最近的一份”内容校验通过且规则
194	// 版本可接受的已保存记录。
195	//
196	// 遍历次序完全来自槽指针维护的历史索引（最新在前），既不依据文件修改
197	// 时间，也不读取受损记录里的父标识或槽首标记：因此最新记录被删除、
198	// 截断成无法解析的内容，或连同若干中间记录一起损坏时，仍能越过它们
199	// 找到本槽更早的可用记录，而不会被引向别的槽或遮住更早的可用记录。
200	// 与世界时间片的大小无关。
201	//
202	// 分支槽只在分支自身已成功保存的记录中查找；即使分支首条记录损坏也不
203	// 越过分支边界，其他槽即使种子和规则相同也不会替代。版本不被接受的
204	// 记录一律跳过且不自动升级。只有记录文件写完且指针已更新（即保存完整
205	// 生效）的记录才在候选中：残留临时文件、写完但尚未完成保存的孤儿记录
206	// 不会被选中。
207	//
208	// 槽不存在返回 *NotFoundError；槽指针不可读返回 *CorruptError；槽中没有
209	// 任何版本可接受的完好记录时返回包装了 ErrUnrecoverable 的
210	// *UnrecoverableError，可用 errors.Is(err, ErrUnrecoverable) 判断。
211	// 恢复读取不会改写槽、指针、历史记录或规则，重复读取也不消耗历史。
212	func (a *Archive) RecoverLatest(slot string, acceptedVersions []string) (Record, error) {
213		if !validSlotName(slot) {
214			return Record{}, &NotFoundError{Slot: slot}
215		}
216		lock, err := acquireSharedLock(a.dir)
217		if err != nil {
218			return Record{}, err
219		}
220		defer lock.release()
221	
222		history, err := a.slotHistoryLocked(slot)
223		if err != nil {
224			return Record{}, err
225		}
226	
227		env, err := a.firstRecoverableLocked(history, acceptedVersions)
228		if err != nil {
229			var ue *UnrecoverableError
230			if errors.As(err, &ue) {
231				ue.Slot = slot
232			}
233			return Record{}, err
234		}
235		return envToRecord(env), nil
236	}
237	
238	// firstRecoverableLocked 在调用方已持锁的前提下，按给定的保存生效次序
239	// （最新在前）返回第一份“内容与父关系校验通过且规则版本可接受”的记录。
240	//
241	// 文件缺失、截断、校验和不符、记录标识不符、父关系异常或世界状态不自洽
242	// 的记录一律越过（不读其中的父标识或槽首标记）；版本不被接受的记录也
243	// 越过且不自动升级。次序完全由调用方给出（来自槽指针历史索引或沿可信
244	// 父链的重建），因此不会被引向别的槽。没有任何可用记录时返回包装了
245	// ErrUnrecoverable 的 *UnrecoverableError（Slot 字段由调用方补全）。
246	func (a *Archive) firstRecoverableLocked(history []RecordID, acceptedVersions []string) (*envelope, error) {
247		var lastReason string
248		for _, id := range history {
249			env, verifyErr := a.loadAndVerifyLocked(id)
250			if verifyErr != nil {
251				lastReason = verifyErr.Error()
252				continue
253			}
254			if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
255				lastReason = (&VersionRejectedError{
256					Record:  id,
257					Version: env.State.Rules.Version,
258				}).Error()
259				continue
260			}
261			return env, nil
262		}
263	
264		if lastReason == "" {
265			lastReason = "槽中没有任何可确认归属的历史记录"
266		}
267		return nil, &UnrecoverableError{Reason: lastReason}
268	}
