63	type VersionRejectedError struct {
64		Slot     string
65		Record   RecordID
66		Version  string
67		Accepted []string
68	}
69	
70	func (e *VersionRejectedError) Error() string {
71		return fmt.Sprintf("world: 记录 %s 的规则版本 %q 不在可接受版本集合 %v 内",
72			e.Record, e.Version, e.Accepted)
73	}
74	
75	// ErrUnrecoverable 表示槽中找不到任何一份校验通过且版本可接受的
76	// 历史记录，无法恢复。调用方可用 errors.Is 判断。
