12	// saveN 在 slot 上连续保存 n+1 条记录（首存 + n 次覆盖），每次把时间片
13	// 推进 i，返回从最新到最旧的记录标识。
14	func saveN(t *testing.T, a *Archive, slot string, n int) []RecordID {
15		t.Helper()
16		w := baseWorld(t)
17		info, err := a.Save(slot, w)
18		if err != nil {
19			t.Fatal(err)
20		}
21		ids := []RecordID{info.ID}
22		cur := info.ID
23		for i := 1; i <= n; i++ {
24			if _, err := w.Apply(Commit{Time: i}); err != nil {
25				t.Fatal(err)
26			}
27			info, err = a.Replace(slot, w, cur)
28			if err != nil {
29				t.Fatal(err)
30			}
31			ids = append([]RecordID{info.ID}, ids...)
32			cur = info.ID
33		}
34		return ids // 最新在前
35	}
36	
37	// corruptChecksum 改写记录文件中的校验和但保留其余 JSON（父标识等仍可解析）。
38	func corruptChecksum(t *testing.T, dir string, id RecordID) {
39		t.Helper()
40		path := recordPath(dir, id)
41		raw, err := os.ReadFile(path)
42		if err != nil {
43			t.Fatal(err)
44		}
45		s := string(raw)
46		i := strings.Index(s, `"checksum": "`)
47		if i < 0 {
48			t.Fatal("找不到 checksum 字段")
49		}
50		start := i + len(`"checksum": "`)
51		s = s[:start] + strings.Repeat("f", 64) + s[start+64:]
52		if err := os.WriteFile(path, []byte(s), 0o600); err != nil {
53			t.Fatal(err)
54		}
55	}
56	
57	// truncateRecord 把记录文件截断成无法解析的内容。
58	func truncateRecord(t *testing.T, dir string, id RecordID) {
59		t.Helper()
60		if err := os.Truncate(recordPath(dir, id), 30); err != nil {
61			t.Fatal(err)
62		}
63	}
64	
65	// deleteRecord 删除记录文件。
66	func deleteRecord(t *testing.T, dir string, id RecordID) {
67		t.Helper()
68		if err := os.Remove(recordPath(dir, id)); err != nil {
69			t.Fatal(err)
70		}
71	}
72	
73	// setRecordField 对记录文件做一次字符串替换（用于篡改父标识/槽首标记），
74	// 不重算校验和。
75	func setRecordField(t *testing.T, dir string, id RecordID, old, neu string) {
76		t.Helper()
77		path := recordPath(dir, id)
78		raw, err := os.ReadFile(path)
79		if err != nil {
80			t.Fatal(err)
81		}
82		got := strings.Replace(string(raw), old, neu, 1)
83		if got == string(raw) {
84			t.Fatalf("记录 %s 中找不到待替换内容 %q", id, old)
85		}
86		if err := os.WriteFile(path, []byte(got), 0o600); err != nil {
87			t.Fatal(err)
88		}
89	}
