91	// TestRecoverAfterLatestDeleted 最新世界记录文件被删除后，仍应恢复到最近
92	// 一份校验通过的记录，删除最新记录后重新打开存档结果一致。
93	func TestRecoverAfterLatestDeleted(t *testing.T) {
94		a, dir := newTestArchive(t)
95		ids := saveN(t, a, "s", 3) // ids[0] 最新, ids[3] 首存
96		deleteRecord(t, dir, ids[0])
97	
98		rec, err := a.RecoverLatest("s", []string{"v1"})
99		if err != nil {
100			t.Fatalf("删除最新记录后应可恢复: %v", err)
101		}
102		if rec.ID != ids[1] {
103			t.Fatalf("应恢复到最近可用记录 %s，得到 %s", ids[1], rec.ID)
104		}
105	
106		a2, err := Open(dir)
107		if err != nil {
108			t.Fatal(err)
109		}
110		rec2, err := a2.RecoverLatest("s", []string{"v1"})
111		if err != nil {
112			t.Fatalf("重开后应可恢复: %v", err)
113		}
114		if rec2.ID != ids[1] {
115			t.Fatalf("重开后恢复结果错误: %s", rec2.ID)
116		}
