119	// TestRecoverAcrossTruncatedAndMultipleCorrupt 最新记录被截断成无法解析的
120	// 内容，且若干中间记录损坏，恢复仍应越过全部受损记录找到更早的完好记录，
121	// 不依赖能否从损坏文件读出父标识。
122	func TestRecoverAcrossTruncatedAndMultipleCorrupt(t *testing.T) {
123		a, dir := newTestArchive(t)
124		ids := saveN(t, a, "s", 4) // r4..r0
125	
126		truncateRecord(t, dir, ids[0]) // 最新：无法解析
127		corruptChecksum(t, dir, ids[1])
128		corruptChecksum(t, dir, ids[2])
129		// ids[3] 完好，ids[4]（首存）也完好；最近可用的是 ids[3]。
130	
131		rec, err := a.RecoverLatest("s", []string{"v1"})
132		if err != nil {
133			t.Fatalf("应越过截断与多条损坏记录恢复: %v", err)
134		}
135		if rec.ID != ids[3] {
136			t.Fatalf("应恢复到 %s，得到 %s", ids[3], rec.ID)
137		}
138		// 返回内容完整保持该次保存：时间片为 1（ids[3] 对应第一次覆盖）。
139		if rec.State.Time != 1 || rec.State.Seed != 42 {
140			t.Fatalf("恢复内容与该次保存不符: %+v", rec.State)
141		}
142		if rec.State.Rules.Version != "v1" {
