151	// TestRecoverTamperedParentDoesNotRedirect 损坏记录里的父标识被改成别的
152	// 值（包括另一条记录的标识），校验和必然失败；恢复次序由槽指针的历史
153	// 索引决定，不能被篡改的父标识引向别的记录，也不能遮住更早的可用记录。
154	func TestRecoverTamperedParentDoesNotRedirect(t *testing.T) {
155		a, dir := newTestArchive(t)
156		ids := saveN(t, a, "s", 3) // r3 r2 r1 r0
157		// 另存一条与本槽无关的记录，伪装成损坏记录里被改写出的“父”。
158		w := baseWorld(t)
159		other, err := a.Save("other", w)
160		if err != nil {
161			t.Fatal(err)
162		}
163		// 篡改最新与一条中间记录的父标识（校验和随之失败）。
164		setRecordField(t, dir, ids[0], `"parent": "`+string(ids[1])+`"`,
165			`"parent": "`+string(other.ID)+`"`)
166		setRecordField(t, dir, ids[2], `"parent": "`+string(ids[3])+`"`,
167			`"parent": "`+string("rdeadbeefdeadbeefdeadbeefdeadbeef")+`"`)
168	
169		rec, err := a.RecoverLatest("s", []string{"v1"})
170		if err != nil {
171			t.Fatalf("应按历史索引越过被篡改记录: %v", err)
172		}
173		if rec.ID != ids[1] {
174			t.Fatalf("最近可用应为 %s，得到 %s", ids[1], rec.ID)
175		}
176	
177		// 恢复绝不能把别的槽的记录当作本槽结果。
178		rec2, err := a.RecoverLatest("s", []string{"v1"})
179		if err != nil || rec2.ID == other.ID {
180			t.Fatalf("恢复被引向了别的槽: %+v err=%v", rec2, err)
181		}
