184	// TestRecoverTamperedSlotFirstDoesNotMask 中间记录的槽首标记被改成 true，
185	// 恢复也不能因此提前停止而遮住本槽更早的可用记录（遍历只看历史索引）。
186	func TestRecoverTamperedSlotFirstDoesNotMask(t *testing.T) {
