203	// TestRecoverOrderIsSaveOrderNotTimeSlice “最近”按该槽保存生效的次序，
204	// 与世界时间片大小无关：保存次序更新的记录时间片反而更小时，恢复次序
205	// 仍以保存次序为准。
206	func TestRecoverOrderIsSaveOrderNotTimeSlice(t *testing.T) {
207		a, dir := newTestArchive(t)
208		// 首存一个时间片为 5 的世界。
209		w0, err := NewWorld(InitialData{
210			Seed:       7,
211			Rules:      baseRules(),
212			Characters: []Character{{ID: "hero", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 1}}}},
213		})
