241		hist, err := a.History("s")
242		if err != nil {
243			t.Fatal(err)
244		}
245		if hist[0].ID != r1.ID || hist[1].ID != r0.ID {
246			t.Fatalf("历史次序应按保存次序: %+v", hist)
247		}
248	
249		// 最新（时间片 1）损坏：应恢复到保存次序更早、但时间片更大的记录。
250		corruptChecksum(t, dir, r1.ID)
251		rec, err := a.RecoverLatest("s", []string{"v1"})
252		if err != nil {
253			t.Fatalf("应按保存次序恢复: %v", err)
254		}
255		if rec.ID != r0.ID || rec.State.Time != 5 {
