260	// TestRecoverBranchBoundary 分支只在分支自身成功保存的记录中恢复，不把
261	// 来源槽记录算进候选；分支首条记录损坏也不越过分支边界，其他槽即使种子
262	// 与规则相同也不能替代。
263	func TestRecoverBranchBoundary(t *testing.T) {
264		a, dir := newTestArchive(t)
265		ids := saveN(t, a, "s", 2) // r2 r1 r0
266		b0, err := a.Branch("s", ids[2], "b")
267		if err != nil {
268			t.Fatal(err)
269		}
270		// 分支再成功保存一条。
271		brec, err := a.Latest("b", []string{"v1"})
272		if err != nil {
273			t.Fatal(err)
274		}
275		wb, err := WorldFromState(brec.State)
276		if err != nil {
277			t.Fatal(err)
278		}
279		if _, err := wb.Apply(Commit{Time: 9}); err != nil {
280			t.Fatal(err)
281		}
282		b1, err := a.Replace("b", wb, b0.ID)
283		if err != nil {
284			t.Fatal(err)
285		}
286	
287		// 分支历史只含分支自身的两条记录。
288		bh, err := a.History("b")
289		if err != nil {
290			t.Fatal(err)
291		}
292		if len(bh) != 2 || bh[0].ID != b1.ID || bh[1].ID != b0.ID {
293			t.Fatalf("分支历史越界: %+v", bh)
294		}
295	
296		// 分支最新记录损坏：应恢复到分支自身更早的记录，而不是来源槽记录。
297		corruptChecksum(t, dir, b1.ID)
298		rec, err := a.RecoverLatest("b", []string{"v1"})
299		if err != nil {
300			t.Fatalf("应恢复到分支自身更早记录: %v", err)
301		}
302		if rec.ID != b0.ID {
303			t.Fatalf("应恢复分支首记录 %s，得到 %s", b0.ID, rec.ID)
304		}
305	
306		// 分支首条记录也损坏：分支全无可用记录，即使来源槽 s 种子规则相同
307		// 也不能替代 -> ErrUnrecoverable。
308		corruptChecksum(t, dir, b0.ID)
309		_, err = a.RecoverLatest("b", []string{"v1"})
310		if !errors.Is(err, ErrUnrecoverable) {
311			t.Fatalf("分支无可用记录应 ErrUnrecoverable，得到 %T: %v", err, err)
312		}
313		// 来源槽依旧可独立恢复，证明两者互不算候选。
314		srec, err := a.RecoverLatest("s", []string{"v1"})
315		if err != nil {
316			t.Fatalf("来源槽应可独立恢复: %v", err)
317		}
318		if srec.ID != ids[0] {
319			t.Fatalf("来源槽恢复结果错误: %s", srec.ID)
320		}
321	}
