349	// TestRecoverFirstSaveCorrupt 首存记录是槽内唯一记录时损坏，不可恢复。
350	func TestRecoverFirstSaveCorrupt(t *testing.T) {
351		a, dir := newTestArchive(t)
352		w := baseWorld(t)
353		r0, err := a.Save("s", w)
354		if err != nil {
355			t.Fatal(err)
356		}
