363	// TestRecoverResidualAndOrphanNotSelected 只有记录文件写完、尚未完成保存
364	// 的残留文件（.tmp）以及写完但指针未提交的孤儿记录都不能被选中。
365	func TestRecoverResidualAndOrphanNotSelected(t *testing.T) {
366		a, dir := newTestArchive(t)
367		w := baseWorld(t)
368		r0, err := a.Save("s", w)
369		if err != nil {
370			t.Fatal(err)
371		}
372		if _, err := w.Apply(Commit{Time: 1}); err != nil {
373			t.Fatal(err)
374		}
375		// 孤儿记录：文件完整，但槽指针没有提交到它。
376		orphan := writeRawRecord(t, a, r0.ID, false, w.Snapshot())
377		// 残留临时文件：无法解析。
378		junk := filepath.Join(dir, recordsName, string(r0.ID)+".tmp")
379		if err := os.WriteFile(junk, []byte("{broken"), 0o600); err != nil {
380			t.Fatal(err)
381		}
