394	// TestRecoverUpgradeChain 升级产生的记录同样支持恢复：升级后最新记录损坏
395	// 时，只接受旧版本的恢复读取找到升级前记录；新旧版本都接受时找到升级后
396	// 之前最近的完好记录。
397	func TestRecoverUpgradeChain(t *testing.T) {
398		a, dir := newTestArchive(t)
399		info := saveBase(t, a, "s")
400		res, err := a.Upgrade("s", []string{"v1"}, v2Rules(), info.ID)
401		if err != nil {
402			t.Fatal(err)
403		}
404		up := res.Record.ID
405		corruptChecksum(t, dir, up)
406	
407		old, err := a.RecoverLatest("s", []string{"v1"})
408		if err != nil {
409			t.Fatalf("应恢复升级前记录: %v", err)
410		}
411		if old.ID != info.ID {
412			t.Fatalf("应恢复 %s，得到 %s", info.ID, old.ID)
413		}
414		// 升级记录损坏后，即便接受 v2 也没有 v2 的完好记录 -> 不可恢复，
415		// 不会把 v1 记录升级后返回。
416		if _, err := a.RecoverLatest("s", []string{"v2"}); !errors.Is(err, ErrUnrecoverable) {
417			t.Fatalf("接受 v2 但 v2 记录损坏时应不可恢复，得到 %T: %v", err, err)
418		}
419	}
