421	// TestRecoverDoesNotMutate 恢复读取不修改目录内容：槽指针文件字节、records
422	// 目录条目集合在多次恢复前后保持一致；不修补损坏记录、不改槽当前记录。
423	func TestRecoverDoesNotMutate(t *testing.T) {
424		a, dir := newTestArchive(t)
425		ids := saveN(t, a, "s", 3)
426		corruptChecksum(t, dir, ids[0])
427		truncateRecord(t, dir, ids[1])
428	
429		snapshot := func() (string, map[string]int64) {
430			ptr, err := os.ReadFile(a.slotPath("s"))
431			if err != nil {
432				t.Fatal(err)
433			}
434			entries, err := os.ReadDir(filepath.Join(dir, recordsName))
435			if err != nil {
436				t.Fatal(err)
437			}
438			m := map[string]int64{}
439			for _, e := range entries {
440				fi, err := e.Info()
441				if err != nil {
442					t.Fatal(err)
443				}
444				m[e.Name()] = fi.Size()
445			}
446			return string(ptr), m
447		}
448	
449		ptrBefore, filesBefore := snapshot()
450		if _, err := a.RecoverLatest("s", []string{"v1"}); err != nil {
451			t.Fatal(err)
452		}
453		if _, err := a.RecoverLatest("s", []string{"v1"}); err != nil {
454			t.Fatal(err)
455		}
456		ptrAfter, filesAfter := snapshot()
457	
458		if ptrBefore != ptrAfter {
459			t.Fatal("恢复读取改写了槽指针")
460		}
461		if len(filesBefore) != len(filesAfter) {
462			t.Fatalf("恢复读取改变了 records 目录条目数: %d -> %d", len(filesBefore), len(filesAfter))
463		}
464		for name, size := range filesBefore {
465			if filesAfter[name] != size {
466				t.Fatalf("恢复读取改动了文件 %s: %d -> %d", name, size, filesAfter[name])
467			}
468		}
469		// 槽当前记录仍是损坏的最新记录，Latest 依旧报损坏。
470		if _, err := a.Latest("s", []string{"v1"}); err == nil {
471			t.Fatal("恢复读取不应修补槽当前记录")
472		}
473	}
474	
475	// TestRecoverCASLoserNotCandidate 并发覆盖同一父记录时竞争失败的写入不
476	// 得进入恢复候选：恰好一个成功，失败者连记录文件都不会留下；胜出记录
477	// 损坏后，恢复只能落到被覆盖的父记录。
478	func TestRecoverCASLoserNotCandidate(t *testing.T) {
479		a, dir := newTestArchive(t)
480		w := baseWorld(t)
481		r0, err := a.Save("s", w)
482		if err != nil {
483			t.Fatal(err)
484		}
485		if _, err := w.Apply(Commit{Time: 1}); err != nil {
486			t.Fatal(err)
487		}
488	
489		const n = 6
490		var wg sync.WaitGroup
491		var mu sync.Mutex
492		wins, conflicts := 0, 0
493		for i := 0; i < n; i++ {
494			wg.Add(1)
495			go func() {
496				defer wg.Done()
497				ga, err := Open(dir)
498				if err != nil {
499					t.Error(err)
500					return
501				}
502				_, err = ga.Replace("s", w, r0.ID)
503				mu.Lock()
504				defer mu.Unlock()
505				switch {
506				case err == nil:
507					wins++
508				case isConflict(err):
509					conflicts++
510				default:
511					t.Errorf("非冲突错误: %v", err)
512				}
513			}()
514		}
515		wg.Wait()
516		if wins != 1 || conflicts != n-1 {
517			t.Fatalf("期望 1 成功 %d 冲突，得到 %d 成功 %d 冲突", n-1, wins, conflicts)
518		}
519	
520		latest, err := a.Latest("s", []string{"v1"})
521		if err != nil {
522			t.Fatal(err)
523		}
524		if latest.Parent != r0.ID {
525			t.Fatalf("胜出记录父应为 %s，得到 %s", r0.ID, latest.Parent)
526		}
527		// 历史只含胜出记录与父记录，竞争失败的写入不在其中。
528		hist, err := a.History("s")
529		if err != nil || len(hist) != 2 {
530			t.Fatalf("历史应只有胜出记录与父记录: %+v err=%v", hist, err)
531		}
532	
533		// 胜出记录损坏：恢复只能落到父记录，绝不会选中任何竞争失败的写入。
534		corruptChecksum(t, dir, latest.ID)
535		rec, err := a.RecoverLatest("s", []string{"v1"})
536		if err != nil {
537			t.Fatalf("应恢复到被覆盖的父记录: %v", err)
538		}
539		if rec.ID != r0.ID {
540			t.Fatalf("应恢复父记录 %s，得到 %s", r0.ID, rec.ID)
541		}
542	}
