544	// TestRecoverReopenAfterInterruptedWrite 写入中断后重新打开，只能看到上一
545	// 次保存完整生效的状态；损坏最新提交记录后，恢复采用的历史次序与之一致，
546	// 不会选中写完但未提交的孤儿记录。
547	func TestRecoverReopenAfterInterruptedWrite(t *testing.T) {
548		a, dir := newTestArchive(t)
549		w := baseWorld(t)
550		r0, err := a.Save("s", w)
551		if err != nil {
552			t.Fatal(err)
553		}
554		if _, err := w.Apply(Commit{Time: 1}); err != nil {
555			t.Fatal(err)
556		}
557		// 新记录已写完但指针尚未提交（崩溃现场），外加一个残留临时文件。
558		orphan := writeRawRecord(t, a, r0.ID, false, w.Snapshot())
559		if err := os.WriteFile(filepath.Join(dir, recordsName, "r00000000000000000000000000000000.tmp"),
560			[]byte("{x"), 0o600); err != nil {
561			t.Fatal(err)
562		}
563	
564		a2, err := Open(dir)
565		if err != nil {
566			t.Fatal(err)
567		}
568		// 指针仍指向上一次完整生效的 r0；把它保持完好，恢复应返回 r0。
569		rec, err := a2.RecoverLatest("s", []string{"v1"})
570		if err != nil {
571			t.Fatalf("重开后应恢复上次完整记录: %v", err)
572		}
573		if rec.ID != r0.ID {
574			t.Fatalf("选中了未提交的孤儿记录 %s 或其它: 得到 %s", orphan, rec.ID)
575		}
576	
577		// 真正提交一条覆盖（r1），随后损坏 r1；恢复仍应越过它回到 r0，
578		// 而不是夹在中间的孤儿记录。
579		latest, err := a2.Latest("s", []string{"v1"})
580		if err != nil {
581			t.Fatal(err)
582		}
583		if _, err := w.Apply(Commit{Time: 2}); err != nil {
584			t.Fatal(err)
585		}
586		r1, err := a2.Replace("s", w, latest.ID)
587		if err != nil {
588			t.Fatal(err)
589		}
590		corruptChecksum(t, dir, r1.ID)
591		rec2, err := a2.RecoverLatest("s", []string{"v1"})
592		if err != nil {
593			t.Fatalf("应越过损坏的新提交恢复: %v", err)
594		}
595		if rec2.ID != r0.ID {
596			t.Fatalf("应恢复 %s，得到 %s（孤儿 %s 不应入选）", r0.ID, rec2.ID, orphan)
597		}
598	}
