608	// TestRecoverLegacyArchiveOpensAndRecovers 已有（旧格式）存档目录应能继续
609	// 打开和读取，无需转换数据；裸指针下恢复仍沿校验通过的父链工作，且读取
610	// 不把指针升级成新格式。
611	func TestRecoverLegacyArchiveOpensAndRecovers(t *testing.T) {
612		a, dir := newTestArchive(t)
613		ids := saveN(t, a, "s", 2) // r2 r1 r0
614		// 把指针降级成旧版本裸指针；记录文件全部完好。
