652	// TestRecoverLegacyFirstWriteGainsFullRecovery 旧槽历史原本完整时，第一次
653	// 成功覆盖后，原有历史与新增记录都获得基于保存次序的恢复能力。
654	func TestRecoverLegacyFirstWriteGainsFullRecovery(t *testing.T) {
655		a, dir := newTestArchive(t)
