657		writeLegacyPointer(t, a, "s", ids[0])
658	
659		a2, err := Open(dir)
660		if err != nil {
661			t.Fatal(err)
662		}
663		// 第一次成功覆盖：内存中重建的完整父链与新记录一起被持久化。
664		latest, err := a2.Latest("s", []string{"v1"})
665		if err != nil {
