671		}
672		if _, err := w.Apply(Commit{Time: 3}); err != nil {
673			t.Fatal(err)
674		}
675		r3, err := a2.Replace("s", w, latest.ID)
676		if err != nil {
677			t.Fatal(err)
678		}
679	
680		p, err := a2.readSlotPointerLocked("s")
681		if err != nil {
682			t.Fatal(err)
683		}
684		want := []RecordID{r3.ID, ids[0], ids[1], ids[2]}
685		if len(p.History) != len(want) {
