687		}
688		for i := range want {
689			if p.History[i] != want[i] {
690				t.Fatalf("历史次序错误: %v", p.History)
691			}
692		}
693	
694		// 新记录与中间记录同时损坏/删除，仍能恢复到旧历史里的首存记录。
695		corruptChecksum(t, dir, r3.ID)
696		deleteRecord(t, dir, ids[0])
697		truncateRecord(t, dir, ids[1])
698		rec, err := a2.RecoverLatest("s", []string{"v1"})
699		if err != nil {
700			t.Fatalf("旧历史获得恢复能力后应找到首存记录: %v", err)
701		}
702		if rec.ID != ids[2] {
703			t.Fatalf("应恢复首存记录 %s，得到 %s", ids[2], rec.ID)
704		}
705	}
706	
707	// TestRecoverLegacyBrokenHistory 旧历史已经断裂且无法确认归属时，只使用
708	// 仍能确认属于该槽的记录；没有可用结果时明确报不可恢复。
709	func TestRecoverLegacyBrokenHistory(t *testing.T) {
710		a, dir := newTestArchive(t)
711		ids := saveN(t, a, "s", 2) // r2 -> r1 -> r0
712		// 删除中间记录 r1，使 r2 的父关系无法验证；指针降级为旧格式。
713		deleteRecord(t, dir, ids[1])
714		writeLegacyPointer(t, a, "s", ids[0])
715	
716		a2, err := Open(dir)
717		if err != nil {
718			t.Fatal(err)
719		}
720		// r2 因父记录缺失无法确认归属，r0 无法经由断裂链确认属于本槽：
721		// 没有可用结果。
722		if _, err := a2.RecoverLatest("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
723			t.Fatalf("断裂且无法确认归属的旧历史应不可恢复，得到 %T: %v", err, err)
724		}
725	}
726	
727	// TestRecoverDeletedMiddleBreaksTipParent 中间记录被删除时，最新记录自身
728	// 内容完好但父记录关系不再成立，按已有校验要求它也算受损；恢复仍应越过
729	// 它与缺失项，落到父记录仍在、自身完好的更早记录。
730	func TestRecoverDeletedMiddleBreaksTipParent(t *testing.T) {
731		a, dir := newTestArchive(t)
732		ids := saveN(t, a, "s", 3)   // r3 r2 r1 r0
733		deleteRecord(t, dir, ids[1]) // 删除 r2：r3 的父记录关系失效
734	
735		// 直接读最新记录应报损坏。
736		if _, err := a.Latest("s", []string{"v1"}); !errors.As(err, new(*CorruptError)) {
737			t.Fatalf("最新记录父关系失效应报损坏，得到 %T: %v", err, err)
738		}
739		rec, err := a.RecoverLatest("s", []string{"v1"})
740		if err != nil {
741			t.Fatalf("应越过父关系失效的最新记录恢复: %v", err)
742		}
743		if rec.ID != ids[2] {
744			t.Fatalf("应恢复父记录仍在的 r1 %s，得到 %s", ids[2], rec.ID)
745		}
746	}
747	
748	// TestRecoverMissingAndCorruptPointer 槽不存在仍报不存在；槽指针不可读
749	// 仍报损坏，本次恢复不处理这两种情况。
750	func TestRecoverMissingAndCorruptPointer(t *testing.T) {
751		a, dir := newTestArchive(t)
752		if _, err := a.RecoverLatest("nope", []string{"v1"}); !errors.As(err, new(*NotFoundError)) {
753			t.Fatalf("槽不存在应 NotFound，得到 %T: %v", err, err)
754		}
