// 前），到槽首条记录为止；分支槽只含它自己保存成功的记录，不会跨入
// 分支来源槽。次序来自槽指针内嵌的历史索引，与文件修改时间无关。该
// 方法只做只读遍历，不改写任何数据；无法解析的记录会被略过。
func (a *Archive) History(slot string) ([]RecordInfo, error) {
	if !validSlotName(slot) {
		return nil, &NotFoundError{Slot: slot}
