// 时间改成零；读取保持只读，不修补这份记录。
func TestLatestAndRecordNegativeTimeCorrupt(t *testing.T) {
	a, _ := newTestArchive(t)
	ids := saveN(t, a, "s", 2) // r2 r1 r0
